function _seo_section($title, $content) {
    return "<h2 style=\"font-size:20px;font-weight:800;color:#0f172a;margin:32px 0 14px;padding-bottom:8px;border-bottom:2px solid #e2e8f0\">{$title}</h2>\n{$content}\n";
}

function _seo_h3($title) {
    return "<h3 style=\"font-size:16px;font-weight:700;color:#1e293b;margin:20px 0 10px\">{$title}</h3>\n";
}

function _seo_p($text) {
    return "<p style=\"font-size:14px;line-height:2;color:#475569;margin-bottom:14px\">{$text}</p>\n";
}

function _seo_ul($items) {
    $html = "<ul style=\"padding-right:20px;margin:10px 0 18px\">\n";
    foreach ($items as $item) {
        $html .= "  <li style=\"font-size:14px;line-height:1.9;color:#475569;margin-bottom:8px\">{$item}</li>\n";
    }
    return $html . "</ul>\n";
}

